      "英文名",
      "不宣称法律或域名可用",
      "仅用作开发任务"
    ],
    "mission": "让剪辑团队清楚比较字幕修改版本，在没有网络时也能复核哪些文字改变。",
    "name_jobs": [
      "形成易辨认的软件产品名",
      "便于团队口头交流",
      "不误导用户以为必须上传文件"
    ],
    "non_jobs": [
      "不必表达全部文件格式",
